import { of, timer } from 'rxjs';
import { map, switchMap } from 'rxjs/operators';
export function passwordMatchValidator(group) {
  const password = group.get('password')?.value;
  const confirmPassword = group.get('confirmPassword')?.value;
  if (!password || !confirmPassword) {
    return null;
  }
  return password === confirmPassword ? null : {
    passwordMismatch: true
  };
}
export function atLeastOnePhoneValidator(control) {
  const phones = control.get('phones');
  if (!phones || phones.length === 0) {
    return {
      noPhones: true
    };
  }
  const hasValue = phones.controls.some(c => !!c.get('number')?.value);
  return hasValue ? null : {
    noPhones: true
  };
}
export function forbiddenUsernameValidator(forbidden) {
  return control => {
    const value = control.value?.toLowerCase?.();
    if (!value) return null;
    return value === forbidden.toLowerCase() ? {
      forbiddenUsername: {
        value
      }
    } : null;
  };
}
export function usernameAvailableValidator(userService) {
  return control => {
    if (!control.value) {
      return of(null);
    }
    return timer(300).pipe(switchMap(() => userService.isUsernameTaken(control.value)), map(isTaken => isTaken ? {
      usernameTaken: true
    } : null));
  };
}
